from decimal import Decimal
from ledgerly.adjustments import issue_credit_note
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError
from ledgerly import audit

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
print(issue_credit_note(inv(), Decimal("10.00"), "goodwill"))
# zero/negative
for a in ("0.00","-1.00"):
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
# exceeds
try: issue_credit_note(inv(), "60.00", "x")
except BillingError as e: print("err", e.code)
# wrong state
try: issue_credit_note(inv("draft"), "10.00", "x")
except BillingError as e: print("err", e.code)
# approval
try: issue_credit_note(inv(price="1000.00"), "600.00", "x")
except BillingError as e: print("err", e.code)
print(issue_credit_note(inv(price="1000.00"), "600.00", "x", approved_by="mgr"))
# idempotency
audit.clear()
a = issue_credit_note(inv(), "10.00", "x", idempotency_key="k1")
b = issue_credit_note(inv(), "10.00", "x", idempotency_key="k1")
print(a == b, len(audit.events("credit_note_issued")))
